css:
.er__item { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 2.3fr); gap: var(--os-space-lg); padding-block: 1.9rem; border-top: 1px solid color-mix(in srgb, var(--os-color-text) 22%, transparent); }
.er__day { margin: 0; font-family: var(--os-font-heading); font-size: 2.4rem; line-height: 1.1; color: var(--os-color-heading); }
.er__meta { margin: .4rem 0 0; font-size: .9rem; line-height: 1.4; color: var(--os-color-text-muted); }
.er__next { display: block; }
.er__next b { color: var(--os-color-link); }
.er__title { margin: 0 0 .7rem; font-size: clamp(1.5rem, 1.2rem + .8vw, 1.85rem); }
.er__sum { margin: 0 0 .9rem; }
.er__more { color: var(--os-color-link); text-decoration: underline; text-underline-offset: .2em; }
@media (max-width: 767px) { .er__item { grid-template-columns: 1fr; gap: .6rem; } .er__day { font-size: 1.9rem; } .er__more { display: inline-flex; align-items: center; min-height: 44px; } }
